    // MARK: - Conflict Resolution Tests

    @Suite("Conflict Resolution")
    struct ConflictResolutionTests {

        @Test("Conflict resolution keeps local when local is newer")
        func keepsLocalWhenNewer() async {
            // Arrange
            let manager = SyncManager()
            let projectId = UUID()

            // Create local project (newer)
            var localProject = VideoProject(id: projectId, name: "Local Project")
            localProject.modifiedAt = Date()

            // Create remote project (older)
            var remoteProject = VideoProject(id: projectId, name: "Remote Project")
            remoteProject.modifiedAt = Date().addingTimeInterval(-3600) // 1 hour older

            // Act
            let result = await manager.resolveConflict(
                projectId: projectId,
                localProject: localProject,
                remoteProject: remoteProject
            )

            // Assert - should keep local version
            #expect(result.name == "Local Project")
            #expect(result.modifiedAt == localProject.modifiedAt)
        }

        @Test("Conflict resolution keeps remote when remote is newer")
        func keepsRemoteWhenNewer() async {
            // Arrange
            let manager = SyncManager()
            let projectId = UUID()

            // Create local project (older)
            var localProject = VideoProject(id: projectId, name: "Local Project")
            localProject.modifiedAt = Date().addingTimeInterval(-3600) // 1 hour older

            // Create remote project (newer)
            var remoteProject = VideoProject(id: projectId, name: "Remote Project")
            remoteProject.modifiedAt = Date()

            // Act
            let result = await manager.resolveConflict(
                projectId: projectId,
                localProject: localProject,
                remoteProject: remoteProject
            )

            // Assert - should keep remote version
            #expect(result.name == "Remote Project")
            #expect(result.modifiedAt == remoteProject.modifiedAt)
        }

        @Test("Conflict resolution with equal times keeps local")
        func keepsLocalWhenEqual() async {
            // Arrange
            let manager = SyncManager()
            let projectId = UUID()
            let sameTime = Date()

            var localProject = VideoProject(id: projectId, name: "Local Project")
            localProject.modifiedAt = sameTime

            var remoteProject = VideoProject(id: projectId, name: "Remote Project")
            remoteProject.modifiedAt = sameTime

            // Act
            let result = await manager.resolveConflict(
                projectId: projectId,
                localProject: localProject,
                remoteProject: remoteProject
            )

            // Assert - with equal times, localProject.modifiedAt > remoteProject.modifiedAt is false
            // so it should keep remote (the else branch)
            #expect(result.name == "Remote Project")
        }

        @Test("Conflict resolution updates status to synced")
        func updatesStatusAfterResolution() async {
            // Arrange
            let manager = SyncManager()
            let projectId = UUID()

            var localProject = VideoProject(id: projectId, name: "Local")
            localProject.modifiedAt = Date()

            var remoteProject = VideoProject(id: projectId, name: "Remote")
            remoteProject.modifiedAt = Date().addingTimeInterval(-60)

            // Act
            _ = await manager.resolveConflict(
                projectId: projectId,
                localProject: localProject,
                remoteProject: remoteProject
            )

            let status = await manager.getStatus(for: projectId)

            // Assert - status should be synced after resolution
            #expect(status == .synced)
        }
    }

    // MARK: - Queue Tests

    @Suite("Sync Queue")
    struct SyncQueueTests {

        @Test("queueProjectForSync updates status when sync enabled")
        func queueUpdatesStatus() async {
            // Arrange
            let manager = SyncManager()
            let projectId = UUID()

            // Enable sync
            await manager.setSyncEnabled(true)

            // Act
            await manager.queueProjectForSync(projectId)
            let status = await manager.getStatus(for: projectId)

            // Assert - should be syncing (pending)
            #expect(status == .syncing)

            // Cleanup
            await manager.setSyncEnabled(false)
        }

        @Test("queueProjectForSync does nothing when sync disabled")
        func queueIgnoredWhenDisabled() async {
            // Arrange
            let manager = SyncManager()
            let projectId = UUID()

            // Ensure sync is disabled
            await manager.setSyncEnabled(false)

            // Act
            await manager.queueProjectForSync(projectId)
            let status = await manager.getStatus(for: projectId)

            // Assert - should remain local (no sync attempted)
            #expect(status == .local)
        }

        @Test("Multiple queue calls are debounced")
        func multipleQueueCallsDebounced() async {
            // Arrange
            let manager = SyncManager()
            let projectId = UUID()
            await manager.setSyncEnabled(true)

            // Act - queue multiple times rapidly
            for _ in 0..<5 {
                await manager.queueProjectForSync(projectId)
            }

            // Wait briefly
            try? await Task.sleep(nanoseconds: 100_000_000)

            let status = await manager.getStatus(for: projectId)

            // Assert - should be in syncing state (debounced)
            #expect(status == .syncing)

            // Cleanup
            await manager.setSyncEnabled(false)
        }
    }

