        @Test("syncProject throws when iCloud not available")
        func syncThrowsWhenNoICloud() async {
            // Note: This test may pass or fail depending on iCloud availability
            // In a real test environment, we'd mock the iCloud container
            let manager = SyncManager()
            let project = VideoProject(name: "Test")

            // Enable sync so the method doesn't return early
            await manager.setSyncEnabled(true)

            // If iCloud is not available, this should throw
            if await !manager.isICloudAvailable {
                await #expect(throws: SyncError.self) {
                    try await manager.syncProject(project)
                }
            }

            // Cleanup
            await manager.setSyncEnabled(false)
        }

